#if UNITY_EDITOR
using System;
using System.Collections;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Security.Cryptography;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

// Native request replay proves UI; session projection below is an adapter, not live networking.
public static class ExertBranchPresentationValidation
{
    const string Base=".tools/exert-branches-1006/ui",Native=".tools/exert-branches-1006/native";
    static readonly BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
    public static string Output {get;private set;}
    public static bool Running {get;private set;}
    [Serializable] class Meta {public string folder,status,runtimeHash;}
    static Transform Root=>GameObject.Find("Canvas").transform;
    static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    static string Hash(string file){using var h=SHA256.Create();return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(file))).Replace("-","").ToLowerInvariant();}
    static string Folder(string name){var p=Native+"/"+name+"-result.json";var m=JsonUtility.FromJson<Meta>(File.ReadAllText(p));Check(m.status=="PASS"&&m.runtimeHash==JsonUtility.FromJson<Meta>(File.ReadAllText("ForgeRuntime/runtime.json")).runtimeHash,"Incomplete/stale native "+name);File.Copy(p,Output+"/inputs/"+name+"-meta.json",true);return m.folder;}
    static ForgeSeatView Read(string name,string label){string p=Path.Combine(Folder(name),label+".json");File.Copy(p,Output+"/inputs/"+name+"-"+label+".json",true);File.AppendAllText(Output+"/input-hashes.tsv",name+"/"+label+"\t"+Hash(p)+"\n");return JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(p));}
    static ForgeSeatView Request(string name,Func<ForgeRequest,bool> match){foreach(string p in Directory.GetFiles(Folder(name),"step-*.json").Where(p=>!p.EndsWith("-other.json")).OrderBy(p=>int.Parse(Path.GetFileNameWithoutExtension(p).Substring(5)))){var v=JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(p));if(match(v.request))return Read(name,Path.GetFileNameWithoutExtension(p)+(v.request.seat==2?"-other":""));}throw new Exception("No native request "+name);}
    static IEnumerator Frame(){yield return new WaitForSecondsRealtime(.2f);yield return new WaitForEndOfFrame();Canvas.ForceUpdateCanvases();}
    static void Clean(){foreach(var p in UnityEngine.Object.FindObjectsByType<ForgeBattlefieldCardPointer>(FindObjectsSortMode.None)){p.ResetHover();p.enabled=false;}}
    static void Click(Button button){Check(button!=null&&button.interactable,"Missing/disabled "+button?.name);var rect=(RectTransform)button.transform;foreach(float y in new[]{.5f,.25f,.75f})foreach(float x in new[]{.5f,.12f,.88f}){var local=new Vector2(Mathf.Lerp(rect.rect.xMin,rect.rect.xMax,x),Mathf.Lerp(rect.rect.yMin,rect.rect.yMax,y));var p=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(local)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(p,hits);if(hits.Count>0&&hits[0].gameObject.GetComponentInParent<Button>()==button){ExecuteEvents.ExecuteHierarchy(hits[0].gameObject,p,ExecuteEvents.pointerClickHandler);return;}}throw new Exception("Ray blocked "+button.name);}
    static Rect Bounds(Transform t){var c=new Vector3[4];((RectTransform)t).GetWorldCorners(c);return Rect.MinMaxRect(c.Min(p=>p.x),c.Min(p=>p.y),c.Max(p=>p.x),c.Max(p=>p.y));}
    static void DockBounds(Transform dock){foreach(var b in dock.GetComponentsInChildren<Button>()){Check(!Bounds(b.transform).Overlaps(Bounds(Root.Find("CornerCluster/ControlRow/PhaseTrack"))),"Phase covered");Check(!Bounds(b.transform).Overlaps(Bounds(Root.Find("PriorityControlMode"))),"AUTO covered");}}
    static IEnumerator Shot(string lang,string label){if(lang!="zh-CN")yield break;ScreenCapture.CaptureScreenshot(Output+"/"+label+".png");yield return Frame();}

    public static void Run(){Check(Application.isPlaying&&!Running,"Play required/already running");Running=true;Output=Base+"/"+DateTime.UtcNow.ToString("yyyyMMddTHHmmssfffffffZ");Directory.CreateDirectory(Output+"/inputs");File.WriteAllText(Base+"/latest.txt",Output);File.WriteAllText(Output+"/result.txt","RUNNING");File.WriteAllText(Output+"/producer-hashes.tsv",string.Join("\n",new[]{"Assets/Scripts/Editor/ExertBranchPresentationValidation.cs","Assets/Scripts/UI/ForgeBattlefieldController.CardSelection.cs","Assets/Scripts/UI/ForgeBattlefieldController.Arena.cs","Assets/Scripts/UI/ForgeBattlefieldController.Integrated.cs","Assets/Scripts/UI/ForgeBattlefieldController.LandChoices.cs","Assets/Scripts/Networking/ForgeWire.cs","Assets/Scripts/Networking/OnlineSpectatorView.cs"}.Select(p=>p+"\t"+Hash(p))));var ui=UnityEngine.Object.FindFirstObjectByType<ForgeBattlefieldController>()??new GameObject("ExertBranchValidation").AddComponent<ForgeBattlefieldController>();ui.StartCoroutine(Guard(ui));}
    static IEnumerator Guard(ForgeBattlefieldController ui){var stack=new Stack<IEnumerator>();stack.Push(Validate(ui));try{while(stack.Count>0){object c;try{var e=stack.Peek();if(!e.MoveNext()){(e as IDisposable)?.Dispose();stack.Pop();continue;}c=e.Current;if(c is IEnumerator nested){stack.Push(nested);continue;}}catch(Exception error){File.WriteAllText(Output+"/result.txt","FAIL "+error);throw;}yield return c;}File.WriteAllText(Output+"/result.txt","PASS: actual native attack-exert selection zero/one, confirm/de-selection/reset and decline indices; view/return stable fonts, stale/duplicate/nonacting guards; actual mana ability both alternatives clicked; typed exert state/blue detail/original view and same-ID expiry across next/following untap in three locales. Equal/different pending exert grouping and face-down spectator projection are adapters. Native effect evidence is separate; no control-change or live-network claim.");}finally{while(stack.Count>0)(stack.Pop() as IDisposable)?.Dispose();Running=false;}}
    static IEnumerator Show(ForgeBattlefieldController ui,ForgeSeatView v,bool act,Action<int> submit){ui.Present(null,v.seat,false,null,null,"");ui.Present(v,v.seat,act,submit,null,"");yield return new WaitForSecondsRealtime(.5f);yield return Frame();Clean();}
    static Button ActionButton(int index)=>GameObject.Find("CardSelection").GetComponentsInChildren<Button>().Single(b=>b.name=="SelectionAction_"+index);
    static void Inspect(ForgeBattlefieldController ui,ForgeCardView card)=>typeof(ForgeBattlefieldController).GetMethod("InspectIntegrated",Hidden).Invoke(ui,new object[]{card});
    static IEnumerator Validate(ForgeBattlefieldController ui){string locale=GamePreferences.Language;bool enabled=ui.enabled;ui.enabled=false;var module=EventSystem.current.currentInputModule;bool input=module!=null&&module.enabled;if(module!=null)module.enabled=false;var notices=UnityEngine.Object.FindObjectsByType<ForgeBattlefieldMigrationNotice>(FindObjectsSortMode.None);var flags=notices.Select(n=>n.enabled).ToArray();foreach(var n in notices)n.enabled=false;
        try{foreach(string lang in new[]{"zh-CN","en-US","ja-JP"}){
            int rev=GamePreferences.Revision;bool change=GamePreferences.Language!=lang;GamePreferences.SetLanguage(lang);float until=Time.realtimeSinceStartup+20;while((!GamePreferences.Ready||change&&rev==GamePreferences.Revision)&&Time.realtimeSinceStartup<until)yield return null;Check(GamePreferences.Ready,"Locale unavailable");yield return Frame();File.AppendAllText(Output+"/steps.log",lang+"\n");
            foreach(int count in new[]{0,1}){
                var v=Read("attack-exert","exert-choice-"+count);Check(v.request.selectionPurpose=="exertAttack","Typed attack purpose absent");int calls=0,last=-1;Action<int> submit=i=>{calls++;last=i;};yield return Show(ui,v,true,submit);var panel=GameObject.Find("CardSelection");var title=panel.transform.Find("Title").GetComponent<Text>();var prompt=panel.transform.Find("Instruction").GetComponent<Text>();Check(title.text==(lang=="zh-CN"?"耗竭":lang=="ja-JP"?"督励":"Exert"),"Exert title wrong");Check(prompt.text.Contains(lang=="zh-CN"?"不选择":lang=="ja-JP"?"選ばず":"without selecting"),"Optional instruction missing");var countLabel=panel.transform.Find("Count").GetComponent<Text>();Check(title.preferredWidth+countLabel.preferredWidth<((RectTransform)panel.transform).rect.width-52,"Header overlaps");var counter=countLabel.GetComponentInChildren<TMPro.TextMeshProUGUI>();if(counter!=null){counter.ForceMeshUpdate();Check(counter.textInfo.lineCount==1&&!counter.isTextOverflowing,"Counter wraps/clips");}Check(!panel.GetComponentsInChildren<Transform>().Any(t=>t.name=="Order"),"Exert invents order number");int font=prompt.fontSize;ui.ViewBattlefield();yield return Frame();Check(panel.GetComponentInParent<CanvasGroup>().alpha==0&&!ui.TrySubmitPresentedOption(ui.OptionIndex("confirm-cards"),v.request.requestId),"Hidden exert selection submits");ui.RestoreBattlefieldWindows();yield return Frame();Check(prompt.fontSize==font,"Restore changed font");yield return Shot(lang,"attack-choice-"+count);
                var option=v.request.options.First(o=>o.card?.name=="Glory-Bound Initiate");int index=ui.OptionIndex(option.id);Check(!ui.TrySubmitPresentedOption(index,v.request.requestId-1),"Stale selection");Click(panel.transform.Find("CardSelectionScroll/Viewport/Content/ChoiceCard_"+option.card.id+"/Artwork")?.GetComponent<Button>()??panel.GetComponentsInChildren<Button>().First(b=>b.transform.parent.name=="ChoiceCard_"+option.card.id));Check(calls==1&&last==index&&!ui.TrySubmitPresentedOption(index,v.request.requestId),"Exact ID/toggle duplicate");
                yield return Show(ui,v,true,submit);Click(ActionButton(ui.OptionIndex("confirm-cards")));Check(calls==2&&last==ui.OptionIndex("confirm-cards"),"Native exert confirm/decline");
                if(count==1){yield return Show(ui,v,true,submit);Click(ActionButton(ui.OptionIndex("reset-cards")));Check(calls==3&&last==ui.OptionIndex("reset-cards"),"Exert reset index");}
                yield return Show(ui,v,false,submit);Check(!ui.TrySubmitPresentedOption(index,v.request.requestId),"Nonacting exert accepted");
            }
            foreach(string mode in new[]{"mana-exert","mana-ordinary"}){var v=Read(mode,"mana-ability");int calls=0,last=-1;Action<int> submit=i=>{calls++;last=i;};yield return Show(ui,v,true,submit);var o=v.request.options.Single(o=>o.id.StartsWith("choice:")&&(o.label.IndexOf("Exert",StringComparison.OrdinalIgnoreCase)>=0)==(mode=="mana-exert"));int index=ui.OptionIndex(o.id);var menu=GameObject.Find("CardAbilityChoices");Check(menu!=null,"Mana alternatives missing");yield return Shot(lang,mode+"-choices");Click(menu.transform.Find("Choices/Viewport/Content/Option_"+index)?.GetComponent<Button>()??menu.GetComponentsInChildren<Button>().Single(b=>b.name=="Option_"+index));Check(calls==1&&last==index,"Mana alternative index");ui.Present(Read(mode,"following-untap"),1,false,null,null,"");yield return Frame();Check(GameObject.Find("CardAbilityChoices")==null,"Ability menu survived next request");}
            foreach(string mode in new[]{"attack-exert","mana-exert"}){
                int id=Read(mode,"before").players[0].battlefield.Single(c=>!c.land).id;
                foreach(string label in new[]{"effect","next-untap","following-untap"}){var v=Read(mode,label);var c=v.players[0].battlefield.Single(c=>c.id==id);ui.Present(v,1,false,null,null,"");yield return Frame();Clean();bool pending=label=="effect";Check((c.exertedBySeats?.Length??0)==(pending?1:0),"Native pending state stale");var badge=GameObject.Find("Card_"+id).GetComponentsInChildren<Transform>().FirstOrDefault(t=>t.name=="Exerted");Check((badge!=null)==pending,"Same-ID exert badge stale");Inspect(ui,c);yield return Frame();var rules=Root.Find("InspectPanel/Rules").GetComponentInChildren<TMPro.TextMeshProUGUI>();string keyword=lang=="zh-CN"?"已耗竭：":lang=="ja-JP"?"督励済み：":"Exerted: ";Check(rules.text.Contains(keyword)==pending,"Same-ID exert detail stale");if(pending){Check(rules.text.Contains("<color=#70BFFF>"+keyword),"Exert detail not blue");yield return Shot(lang,mode+"-details");Click(Root.Find("InspectPanel/OriginalState").GetComponent<Button>());yield return Frame();Check(!rules.text.Contains(keyword),"Original invents exert state");Click(Root.Find("InspectPanel/OriginalState").GetComponent<Button>());yield return Frame();}
                }
            }
            if(lang=="zh-CN"){
                var c=Read("mana-exert","effect").players[0].battlefield.Single(c=>!c.land);var clone=JsonUtility.FromJson<ForgeCardView>(JsonUtility.ToJson(c));clone.id++;Check(ForgeBattlefieldController.ArenaGroupKey(c)==ForgeBattlefieldController.ArenaGroupKey(clone),"Equal exert cannot group");clone.exertedBySeats=Array.Empty<int>();Check(ForgeBattlefieldController.ArenaGroupKey(c)!=ForgeBattlefieldController.ArenaGroupKey(clone),"Different pending exert collapses");var method=typeof(OnlineSpectatorView).GetMethod("PublicCard",BindingFlags.Static|BindingFlags.NonPublic);c.faceDown=true;var publicCard=(ForgeCardView)method.Invoke(null,new object[]{c});Check(publicCard.exertedThisTurn==c.exertedThisTurn&&publicCard.exertedBySeats.SequenceEqual(c.exertedBySeats)&&publicCard.printingKey==null,"Public face-down exert loses state/leaks face");
            }
        }}finally{ui.Present(null,1,false,null,null,"");ui.enabled=enabled;GamePreferences.SetLanguage(locale);if(module!=null)module.enabled=input;for(int i=0;i<notices.Length;i++)if(notices[i]!=null)notices[i].enabled=flags[i];}
    }
}
#endif
